using System;using System.Text;using System.Collections.Generic;using System.Reflection;using System.Globalization;using System.Threading;using OpenSim.Framework;
namespace OpenSim.Framework{public static class Util{public static double GetTimeStampMS(){F.Trace+="clock;";F.Fail(1,"clock");return F.Now;}}}
namespace System.Threading{public sealed class Timer:IDisposable{public Timer(TimerCallback callback,object state,int due,int period){F.Trace+="timer:"+due+";";F.Fail(2,"timer");}public bool Change(int due,int period){F.Trace+="change:"+due+";";F.Fail(4,"change");return true;}public void Dispose(){F.Trace+="dispose-timer;";F.Fail(8,"dispose-timer");}}}
static class F{
 public static double Now;public static string Trace;public static int Flags;
 public static void Fail(int f,string message){if((Flags&f)!=0)throw new Exception(message);}
 public static string H(string s)=>Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();
 static object Field(object value,string name)=>value.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(value);
 static string State(ExpiringCacheOS<string,int> cache){if(cache==null)return "N";var expires=(Dictionary<string,int>)Field(cache,"m_expireControl");var values=(Dictionary<string,int>)Field(cache,"m_values");var pairs=new List<string>();foreach(var e in expires)pairs.Add(e.Key+"="+e.Value);var vals=new List<string>();foreach(var e in values)vals.Add(e.Key+"="+e.Value);return cache.Count+":"+string.Join(',',pairs)+":"+string.Join(',',vals)+":"+(Field(cache,"m_purgeTimer")==null?0:1)+":"+(Field(cache,"m_rwLock")==null?0:1);}
 static string Key(string value)=>value=="_"?null:value;
 static double Number(string s)=>s=="nan"?double.NaN:s=="inf"?double.PositiveInfinity:s=="-inf"?double.NegativeInfinity:double.Parse(s,CultureInfo.InvariantCulture);
 static void Main(){CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;string line;while((line=Console.ReadLine())!=null){var args=line.Split(' ');int interval=int.Parse(args[0]);Flags=int.Parse(args[1]);Now=0;Trace="";ExpiringCacheOS<string,int> cache=null;int[] saved=null;var results=new List<string>();try{cache=new ExpiringCacheOS<string,int>(interval);GC.SuppressFinalize(cache);results.Add("NEW:"+State(cache));}catch(Exception e){results.Add("EX:"+H(e.Message));}foreach(var token in args[2..]){string result="OK";try{var p=token[1..].Split(':');string key=Key(p[0]);switch(token[0]){case 't':Now=Number(p[0]);break;case 'f':Flags=int.Parse(p[0]);break;case 'a':cache.Add(key,int.Parse(p[1]),int.Parse(p[2]));break;case 'd':cache.Add(key,int.Parse(p[1]));break;case 'i':cache.AddOrUpdate(key,int.Parse(p[1]),int.Parse(p[2]));break;case 'j':cache.AddOrUpdate(key,int.Parse(p[1]),Number(p[2]));break;case 'r':result=cache.Remove(key)?"1":"0";break;case 'c':cache.Clear();break;case 'k':result=cache.ContainsKey(key)?"1":"0";break;case 'h':result=cache.Contains(key,int.Parse(p[1]))?"1":"0";break;case 'g':result=(cache.TryGetValue(key,out int val)?"1":"0")+":"+val;break;case 'l':result=(cache.TryGetValue(key,int.Parse(p[1]),out int value)?"1":"0")+":"+value;break;case 'q':ref int def=ref cache.TryGetOrDefaultValue(key,out bool existed);result=(existed?"1":"0")+":"+def;break;case 's':ref int slot=ref cache.TryGetOrDefaultValue(key,int.Parse(p[1]),out bool found);result=(found?"1":"0")+":"+slot;break;case 'v':var arr=cache.Values;result=(ReferenceEquals(arr,saved)?"1":"0")+":"+string.Join(',',arr);saved=arr;break;case 'w':saved[0]=99;break;case 'b':result=saved==null?"N":string.Join(',',saved);break;case 'p':cache.GetType().GetMethod("Purge",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cache,new object[]{null});break;case 'u':((ReaderWriterLockSlim)Field(cache,"m_rwLock")).ExitWriteLock();break;case 'z':cache.Dispose();break;case 'n':result=cache.Count.ToString();break;}}catch(Exception e){if(e is TargetInvocationException&&e.InnerException!=null)e=e.InnerException;result="EX:"+H(e.Message);}results.Add(result+":"+State(cache));}Console.WriteLine(string.Join('/',results)+"|"+H(Trace));}}
}
